INSERT INTO `posts` (`id`, `title`, `slug`, `content`, `excerpt`, `image`, `category`, `status`, `author_id`, `created_at`, `updated_at`, `views`) VALUES ('7', 'Ditlantas Polda Bengkulu Peringati Hari Lalu Lintas Bhayangkara ke-71 dengan Pelayanan Presisi', 'hut-lalu-lintas-bhayangkara-71-polda-bengkulu', 'Dalam rangka memperingati Hari Lalu Lintas Bhayangkara ke-71 tahun 2026, Direktorat Lalu Lintas (Ditlantas) Polda Bengkulu menyelenggarakan serangkaian kegiatan bakti sosial, edukasi tertib berlalu lintas di sekolah-sekolah, dan penguatan pelayanan SIM/Samsat keliling bagi masyarakat Bengkulu.', 'Dalam rangka memperingati Hari Lalu Lintas Bhayangkara ke-71 tahun 2026, Direktorat Lalu Lintas (Ditlantas) Polda Bengkulu menyelenggarakan serangkaian kegiatan bakti sosial, edukasi tertib berlalu li...', NULL, 'berita', 'published', '1', '2026-09-22 09:00:00', '2026-09-22 09:00:00', '0');
INSERT INTO `posts` (`id`, `title`, `slug`, `content`, `excerpt`, `image`, `category`, `status`, `author_id`, `created_at`, `updated_at`, `views`) VALUES ('8', 'Ditreskrimsus Polda Bengkulu Ungkap Kasus Praktik Ilegal Tanpa Izin di Kota Bengkulu', 'ditreskrimsus-ungkap-praktik-ilegal', 'Subdit Indagsi Ditreskrimsus Polda Bengkulu berhasil mengungkap praktik ilegal pelayanan medis dan estetika tanpa izin resmi di wilayah Kota Bengkulu. Pengungkapan ini merupakan bentuk komitmen kepolisian dalam melindungi masyarakat dari risiko kesehatan akibat layanan tanpa legalitas.', 'Subdit Indagsi Ditreskrimsus Polda Bengkulu berhasil mengungkap praktik ilegal pelayanan medis dan estetika tanpa izin resmi di wilayah Kota Bengkulu. Pengungkapan ini merupakan bentuk komitmen kepoli...', NULL, 'berita', 'published', '1', '2026-09-21 14:30:00', '2026-09-21 14:30:00', '0');
INSERT INTO `posts` (`id`, `title`, `slug`, `content`, `excerpt`, `image`, `category`, `status`, `author_id`, `created_at`, `updated_at`, `views`) VALUES ('9', 'Subdit Ditresnarkoba Polda Bengkulu Amankan Tersangka Pengedar Narkotika dalam Pengembangan Kasus', 'ditresnarkoba-amankan-pengedar-sabu-bengkulu', 'Jajaran Ditresnarkoba Polda Bengkulu kembali menunjukkan komitmen pemberantasan narkotika dengan mengamankan terduga pengedar narkotika di kawasan Rawa Makmur, Kota Bengkulu, beserta barang bukti tujuh paket sabu siap edar.', 'Jajaran Ditresnarkoba Polda Bengkulu kembali menunjukkan komitmen pemberantasan narkotika dengan mengamankan terduga pengedar narkotika di kawasan Rawa Makmur, Kota Bengkulu, beserta barang bukti tuju...', NULL, 'berita', 'published', '1', '2026-09-15 16:00:00', '2026-09-15 16:00:00', '0');
INSERT INTO `posts` (`id`, `title`, `slug`, `content`, `excerpt`, `image`, `category`, `status`, `author_id`, `created_at`, `updated_at`, `views`) VALUES ('10', 'Capaian Operasi Musang Nala 2026: Jajaran Polda Bengkulu Berhasil Ungkap 93 Kasus Kejahatan 3C', 'capaian-operasi-musang-nala-2026', 'Hasil evaluasi Operasi Musang Nala 2026 mencatat Polda Bengkulu dan Polres jajaran berhasil mengungkap 93 kasus tindak pidana konvensional (Curat, Curas, dan Curanmor) dengan 110 tersangka yang berhasil diamankan di seluruh wilayah hukum Provinsi Bengkulu.', 'Hasil evaluasi Operasi Musang Nala 2026 mencatat Polda Bengkulu dan Polres jajaran berhasil mengungkap 93 kasus tindak pidana konvensional (Curat, Curas, dan Curanmor) dengan 110 tersangka yang berhas...', NULL, 'berita', 'published', '1', '2026-08-10 10:15:00', '2026-08-10 10:15:00', '2');
INSERT INTO `posts` (`id`, `title`, `slug`, `content`, `excerpt`, `image`, `category`, `status`, `author_id`, `created_at`, `updated_at`, `views`) VALUES ('11', 'Kapolda Bengkulu Irjen Pol Yudhi Sulistianto Wahid Pimpin Apel Kesiapsiagaan Kamtibmas', 'kapolda-bengkulu-pimpin-apel-kesiapsiagaan-2026', 'Kapolda Bengkulu Irjen Pol Yudhi Sulistianto Wahid, S.I.K. memimpin apel gelar pasukan kesiapsiagaan personel jajaran dalam rangka menjaga stabilitas keamanan dan ketertiban masyarakat (Kamtibmas) di seluruh wilayah Provinsi Bengkulu.', 'Kapolda Bengkulu Irjen Pol Yudhi Sulistianto Wahid, S.I.K. memimpin apel gelar pasukan kesiapsiagaan personel jajaran dalam rangka menjaga stabilitas keamanan dan ketertiban masyarakat (Kamtibmas) di ...', NULL, 'berita', 'published', '1', '2026-09-10 08:00:00', '2026-09-10 08:00:00', '1');
INSERT INTO `posts` (`id`, `title`, `slug`, `content`, `excerpt`, `image`, `category`, `status`, `author_id`, `created_at`, `updated_at`, `views`) VALUES ('12', 'Wakapolda Bengkulu Kombes Pol Prianto Teguh Nugroho Tinjau Inovasi Pelayanan Publik Presisi Polres Jajaran', 'wakapolda-tinjau-pelayanan-publik-presisi-2026', 'Wakapolda Bengkulu Kombes Pol. Prianto Teguh Nugroho, S.I.K., M.H., CPM., CPLA. melaksanakan kunjungan kerja sekaligus supervisi ke sentra-sentra pelayanan publik SPKT, SKCK, dan Satpas SIM di wilayah hukum jajaran Polres untuk memastikan pelayanan prima.', 'Wakapolda Bengkulu Kombes Pol. Prianto Teguh Nugroho, S.I.K., M.H., CPM., CPLA. melaksanakan kunjungan kerja sekaligus supervisi ke sentra-sentra pelayanan publik SPKT, SKCK, dan Satpas SIM di wilayah...', NULL, 'pengumuman', 'published', '1', '2026-09-18 11:00:00', '2026-09-18 11:00:00', '0');
